// Scan state files for sessions that need BaseCommit updates:
// - ACTIVE sessions: keep BaseCommit in sync so PrepareCommitMsg finds them
// - Sessions with carry-forward files: advance BaseCommit so they stay on
//   the current shadow branch (discoverable by findSessionsFromShadowTree)
// This is cheap — JSON parse + field checks only, no git ref lookups.
sessions, err := s.findActiveOrCarryForwardSessions(ctx, worktreePath)
if err != nil || len(sessions) == 0 {
	return
}

newHead := head.Hash().String()
repo, repoErr := OpenRepository(ctx)

for _, state := range sessions {
	if state.BaseCommit == newHead {
		continue
	}
	if state.Phase.IsActive() {
		logging.Debug(logCtx, "post-commit (no trailer): updating BaseCommit",
			slog.String("session_id", state.SessionID),
			slog.String("old_base", truncateHash(state.BaseCommit)),
			slog.String("new_head", truncateHash(newHead)),
		)
		state.BaseCommit = newHead
		if err := s.saveSessionState(ctx, state); err != nil {
			logging.Warn(logCtx, "failed to update session state",
				slog.String("session_id", state.SessionID),
				slog.String("error", err.Error()))
		}
	} else if len(state.FilesTouched) > 0 && repoErr == nil {
		// Carry-forward session: advance BaseCommit and re-carry-forward
		// to the new shadow branch so it stays discoverable.
		state.BaseCommit = newHead
		s.carryForwardToNewShadowBranch(ctx, repo, state, state.FilesTouched)
		logging.Debug(logCtx, "post-commit (no trailer): advanced carry-forward",
			slog.String("session_id", state.SessionID),
			slog.String("new_head", truncateHash(newHead)),
			slog.Int("files_carried", len(state.FilesTouched)),
		)
		if err := s.saveSessionState(ctx, state); err != nil {
			logging.Warn(logCtx, "failed to save carry-forward state",
				slog.String("session_id", state.SessionID),
				slog.String("error", err.Error()))
		}
	}

